CREATE FUNCTION public.preserve_fiscal_original_extraction() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.extracted_rows IS DISTINCT FROM OLD.extracted_rows OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.file_hash IS DISTINCT FROM OLD.file_hash OR NEW.storage_path IS DISTINCT FROM OLD.storage_path OR NEW.file_name IS DISTINCT FROM OLD.file_name OR NEW.warnings IS DISTINCT FROM OLD.warnings THEN RAISE EXCEPTION 'Original fiscal extraction is immutable; edit corrected_rows instead'; END IF; RETURN NEW; END; $$; CREATE TRIGGER preserve_fiscal_original BEFORE UPDATE ON public.fiscal_document_runs FOR EACH ROW EXECUTE FUNCTION public.preserve_fiscal_original_extraction();